      gsRefCritBlankName: "A blank name is saved as Criterion {n}.",
      gsMenuPrintSemGradesLabel: "Print {sem} grades",
      gsTestMetaDesc: "Editable test sheet with weighted criteria. Test coefficient is used in term averages.",
      gsGradingManualTotalPts: "Total available points: {total}.",
      gsGradingManualNeedCrit: "Points mode needs criteria total points. Add criteria first.",
      gsGradingManualSetPct: "Set minimum percentages for each grade.",
      gsNoCriteriaYet: "No criteria yet.",
      gsTestTourNeedTest: "Open a test first to start the tour.",
      tutGs1Title: "Test Header",
      tutGs1Text: "Shows the class name, term, and test label. The line below is a quick reminder that the sheet uses weighted criteria.",
      tutGs2Title: "Actions",
      tutGs2Text: "Test Options: full settings panel (grading, criteria, info). Criteria Reference: view all correction criteria and grading scales. Apply Criteria: auto-calculate grades from criteria totals. Print Results: print or export. Duplicate / Import: copy criteria and config from another test. Delete / Clear: remove or reset the test.",
      tutGs3Title: "Config Chips",
      tutGs3Text: "Click any chip to open its editor. Coefficient: how much this test counts toward the term average, or a fixed percentage weight. Grading Scale: the grade thresholds (e.g. 60% → 4). Criteria: scored sections of the test with max points and coefficients. Test Info: name, date, scope, type, and next-grade highlight threshold.",
      tutGs4Title: "Table Columns",
      tutGs4Text: "Fixed columns: student index, first name, last name. Computed columns: Grade (from the grading scale), Next Grade Δ (points needed to reach the next grade), Observations (free text), total Points, and Time. Criterion columns follow — click any criterion header to edit its name, max points, coefficient, or bonus status.",
      tutGs5Title: "Grade Entry",
      tutGs5Text: "Each row is one student. Click a cell in a criterion column to type the score. Tab moves to the next cell. Grade and Points recalculate instantly. The Observations cell accepts free-text notes. Click a student name to open their student card.",
      tutGsM1Title: "Test Info",
      tutGsM1Text: "Give the test a name (shown in column headers), a date, the scope (chapters or units covered), and the type (Written, Oral, Quiz…). Use the Term chips to move this test to a different semester. Next-grade highlight: students within that many points of the next grade up are highlighted green in the sheet. Set to 0 to disable.",
      tutGsM2Title: "Coefficient",
      tutGsM2Text: "Controls how much this test weighs in the term average. Coefficient mode: proportional weighting — a coeff 2 test counts twice as much as a coeff 1 test. Fixed weight %: this test always contributes exactly that percentage of the term average, regardless of how many other tests exist.",
      tutGsM3Title: "Grading Scale",
      tutGsM3Text: "Sets how raw scores convert to grades. Formula: enter one percentage threshold for grade 4 and pick a scale model — all other grade thresholds are calculated proportionally. Manual % per grade: set each grade's minimum percentage manually. Manual pts per grade: set the minimum number of points per grade directly — useful when point totals are fixed. The Scale model selector loads named presets from the Criteria / Scales reference data.",
      tutGsM4Title: "Criteria",
      tutGsM4Text: "Criteria are the scored sections of the test (e.g. Vocabulary, Grammar, Writing). Drag rows to reorder; click a row to edit it inline. Max: maximum points for that section. Coeff: a per-criterion weight applied before adding to the total. Bonus: does not count toward the possible total — it can only increase a student's score. The Preset selector loads a saved criterion template. The × field adds multiple identical criteria at once.",
      tutGsM5Title: "Save & Close",
      tutGsM5Text: "Save applies all changes immediately and recalculates every student's grade. Close discards unsaved changes. Modifying criteria preserves existing scores for criteria whose IDs are unchanged; new criteria start blank and deleted criteria lose their scores.",
      tutGsM6Title: "Live Preview Tab",
      tutGsM6Text: "Preview how raw point totals map to grades (1.0 to 6.0) under your current scale settings.",
      gsToptTabInfo: "General Info",
      gsToptTabCoeff: "Weighting",
      gsToptTabGrading: "Grading Scale",
      gsToptTabCriteria: "Criteria",
      gsToptTabPreview: "Grade Preview",
      gsToptPreviewTitle: "Live Grade Simulation",
      gsToptPreviewHelp: "Live point-to-grade mapping based on current criteria total and grading scale parameters.",
      gsToptPreviewPts: "Points Range",
      gsToptPreviewGrade: "Grade",
      gsToptPreviewPct: "% of Max",
      tutGsC1Title: "Grade Sheet Overview",
      tutGsC1Text: "Welcome to Grade Sheet! This main page displays all your class cards and quick actions for managing tests and reference data.",
      tutGsC2Title: "Class Cards Grid",
      tutGsC2Text: "Each card displays a class summary with student count, test count, and average grade. Click any class card to open its full grade matrix.",
      tutGsC3Title: "Add Class & Add Test",
      tutGsC3Text: "Use \"+ Add Class\" to set up a new class roster, or \"Add Test\" to create a new evaluation column across your classes.",
      tutGsC4Title: "Export & Import Data",
      tutGsC4Text: "Export JSON creates a backup of all class rosters, grades, criteria, and scale configs. Import JSON restores or loads grade sheet data files.",
      tutGsC5Title: "Edit Criteria & Scales (In Depth)",
      tutGsC5Text: "Central bank for all evaluation standards!\n• Correction Criteria: define reusable evaluation items (Vocabulary, Grammar, etc.) with default max points, weights, and grade descriptors.\n• Grading Scale Models: configure threshold curves (% points needed for each grade) used to calculate final grades.\n• Personalised Observation Chips: customize quick comment tags for student observations.\nSaved items update test options and templates system-wide.",
      tutGsS1Title: "Class Summary Header",
      tutGsS1Text: "Displays the class name and instructions. This view shows the master gradebook for all terms of the selected class.",
      tutGsS2Title: "Term Filter Chips",
      tutGsS2Text: "Switch between Semester 1 (S1), Semester 2 (S2), or Full Year views. Filtering by term updates test columns and term averages dynamically.",
      tutGsS3Title: "Grade Matrix Table",
      tutGsS3Text: "Lists every student alongside their test scores (T1, T2...), computed averages, and class statistics. Click any test column header (T1, T2...) to open and edit that specific test sheet.",
      tutGsS4Title: "Add & Import Tests",
      tutGsS4Text: "Add Test creates a new test for this class. Import Test allows copying a test configuration from another class or semester.",
      tutGsS5Title: "Roster & Class Management",
      tutGsS5Text: "Add Student adds new students to this grade sheet. Edit Class modifies class name, term dates, or semester weighting coefficients.",
      tutGsS6Title: "Export & Import Grades",
      tutGsS6Text: "Export summary reports to PDF, HTML, DOCX, CSV, or XLSX. Import Grades imports student scores directly from spreadsheet files.",
      tutGsR1Title: "Reference Data Categories",
      tutGsR1Text: "Switch between Correction Criteria, Grading Scale Models, and Personalised Chips tabs to manage your reusable evaluation presets.",
      tutGsR2Title: "Correction Criteria Templates",
      tutGsR2Text: "Add, rename, or duplicate evaluation criteria. Set default max points, coefficient weights, and grade level descriptors.",
      tutGsR3Title: "Grading Scale Models",
      tutGsR3Text: "Configure custom grading scale models and minimum percentage thresholds per grade for automated grade calculation.",
      tutGsR5Title: "Personalised Chips Tab",
      tutGsR5Text: "Configure quick-click observation categories and custom tags used for teacher feedback notes when evaluating students.",
      tutGsR4Title: "Save Reference Data",
      tutGsR4Text: "Click Save to persist changes to user/correction-criteria.js and user/grade-scale-models.js. All test presets update immediately.",
