      conInstructions: "System: right-click the board to add words (comma = separate, + = grouped, -- = linked chain) · Move: drag words and drop onto another word to group · Multi-select: Ctrl/Cmd+click, then right-click selection to align, distribute, or grid · Shortcuts: Ctrl/Cmd+G group, Ctrl/Cmd+A select all, Ctrl/Cmd+H hide/reveal, Delete/Backspace remove selection, Ctrl/Cmd+↑/↓ increase/decrease font size, Esc close menus, Ctrl/Cmd+Z undo, Ctrl/Cmd+Y or Ctrl/Cmd+Shift+Z redo, Ctrl/Cmd+S save",
