      alert_select_before_save: "Veuillez sélectionner un groupe avant de sauvegarder.",
      alert_no_sessions_export: "Aucune session à exporter.\nUtilisez Enregistrer d'abord.",
      confirm_import: "Vous avez déjà {n} session(s) dans votre base de données.\n\nCliquez sur OK pour FUSIONNER (les sessions importées s'ajoutent).\nCliquez sur Annuler pour REMPLACER (écrase vos données actuelles).",
      alert_import_ok: "Importation réussie !\n{n} session(s) dans la base de données.",
      alert_import_fail: "Échec de l'importation : {e}\n\nAssurez-vous d'importer un fichier exporté depuis cette application.",
      alert_no_groups: "Aucun groupe trouvé.",
      tm_no_sessions: "Aucune session enregistrée.\nUtilisez Enregistrer pour créer une entrée.",
      tm_readonly_badge: "Lecture seule",
      help_s_groups_title: "Groupes",
      help_s_groups_p: "Sélectionnez un groupe de classe à l'aide des boutons en haut de la page. La liste se met à jour immédiatement. Vous pouvez changer de groupe à tout moment — les points et les barres sont sauvegardés par groupe pour toute la durée de la session.",
      help_s_picker_title: "Tirage aléatoire",
      help_s_picker_p: "Appuyez sur Tirage aléatoire (ou Ctrl + Espace) pour sélectionner un élève au hasard. Les élèves déjà tirés sont barrés pour éviter les répétitions. Cliquez directement sur le nom d'un élève pour le barrer manuellement — utile en cas d'absence. Utilisez Réinitialiser les barres dans la barre utilitaire pour recommencer un tour. Pour plus de suspense, cliquez sur Roulement de tambour avant le tirage.",
      help_s_points_title: "Points",
      help_s_points_p: "Chaque élève dispose de boutons + et -. Le plus attribue un point de participation ; le moins enregistre un avertissement ou une tâche non effectuée. Les compteurs vert et rouge à côté de chaque élève sont cliquables : cliquer dessus diminue le compteur d'un point, pour corriger une erreur. Les scores alimentent le classement en direct et les résultats de fin de session.",
      help_s_badges_title: "Badges",
      help_s_badges_p: "Chaque élève peut recevoir des badges emoji en récompense. Cliquez sur le bouton badge d'une ligne pour ouvrir le sélecteur, puis cliquez sur un badge pour l'attribuer. Les badges s'accumulent et apparaissent à côté des noms. Utilisez le bouton Badges dans l'en-tête pour afficher ou masquer la colonne. Pour retirer un badge, cliquez directement sur la puce badge de la ligne de l'élève.",
      help_s_notes_title: "Notes",
      help_s_notes_p: "Cliquez sur l'indicateur de point d'une ligne pour ouvrir un popup de note privée. Saisissez une courte note (ex. \"a besoin d'aide pour la tâche 3\", \"absent la semaine dernière\") et appuyez sur Entrée ou Enregistrer. Les notes sont privées — elles n'apparaissent pas à l'écran et ne sont visibles que dans le popup. Un point rempli indique qu'une note existe.",
      help_s_timer_title: "Minuteur",
      help_s_timer_p: "Cliquez sur Minuteur dans le menu pour ouvrir le popup. Définissez la durée en heures et minutes, configurez le nombre de bips de fin, puis appuyez sur Démarrer. Le compte à rebours apparaît dans la barre de menu et est cliquable pour rouvrir le popup. Appuyez sur pour ouvrir un écran plein couleur — utile pour le vidéoprojecteur : il passe du vert à l'orange au rouge lorsque le temps est presque écoulé.",
      help_s_objectives_title: "Objectifs de la leçon",
      help_s_objectives_p: "Cliquez sur Objectifs dans le menu pour ouvrir l'éditeur. Saisissez un ou plusieurs objectifs et enregistrez — ils apparaissent dans une barre sous le titre et dans le minuteur plein écran. Cliquez sur le texte de la barre ou sur le bouton Modifier pour les mettre à jour. Activez ou désactivez la barre avec le bouton Objectifs.",
      help_s_mode_title: "Mode classe",
      help_s_mode_p: "Appuyez sur Mode dans le menu (ou Ctrl + M) pour choisir un mode de travail : Silence, Discussion ou Travail en groupe. Chaque mode ouvre un écran plein animé conçu pour être projeté à la classe. Vous pouvez aussi lancer un mode directement depuis le popup Minuteur via les trois boutons raccourcis en bas. Appuyez sur le bouton de fermeture ou Ctrl + M pour quitter.",
      help_s_teams_title: "Équipes",
      help_s_teams_p: "Appuyez sur Créer des équipes (ou Ctrl + Shift + K) pour ouvrir le créateur d'équipes. Choisissez un nombre total d'équipes ou un nombre d'élèves par équipe — le système répartit aléatoirement et attribue une couleur à chaque équipe. Vous pouvez glisser-déposer des élèves entre les équipes pour les rééquilibrer. Faites glisser une carte d'équipe sur une autre pour les fusionner. Utilisez Remélanger pour redistribuer, ou Supprimer les équipes pour revenir à la liste standard.",
      help_s_roles_title: "Rôles dans les équipes",
      help_s_roles_p: "Une fois les équipes créées, cliquez sur Rôles pour ouvrir l'éditeur. Utilisez le bouton + pour ajouter des noms de rôles (ex. Capitaine, Secrétaire, Chronomètre, Porte-parole). Cliquez sur Distribuer aux élèves pour attribuer aléatoirement un rôle par élève dans toutes les équipes. Les rôles apparaissent en italique. Utilisez Réinitialiser tous les rôles pour les effacer.",
      help_s_results_title: "Résultats et classement",
      help_s_results_p: "Cliquez sur Résultats &amp; Classement pour ouvrir le panneau de résultats en direct. La partie supérieure affiche le classement complet trié par score. La partie inférieure montre le podium Performance du jour — élèves Or, Argent et Bronze — ainsi que les scores moyens des équipes si des équipes sont actives.",
      help_s_history_title: "Historique de la session",
      help_s_history_p: "Cliquez sur Historique pour consulter le journal chronologique de toutes les actions — points attribués, badges, notes et élèves tirés. Les événements les plus récents apparaissent en premier. Utilisez Exporter CSV pour télécharger le journal. Utilisez Effacer pour réinitialiser le journal.",
      help_s_db_title: "Base de données &amp; Machine à remonter le temps",
      help_s_db_p1: "Cliquez sur DB dans le menu pour ouvrir le panneau. Utilisez Enregistrer pour sauvegarder la classe sélectionnée, ou Tout enregistrer pour sauvegarder tous les groupes en une fois. Si une classe a déjà été sauvegardée aujourd'hui, elle est silencieusement écrasée ; sinon, une nouvelle entrée est créée.",
      help_s_db_p2: "Cliquez sur Machine à remonter le temps pour parcourir les sessions. Appuyez sur Afficher sur une entrée pour charger ce snapshot — l'application passe en mode lecture seule. Une bannière violette indique quelle session est affichée. Appuyez sur Retour en direct pour restaurer votre session.",
      help_s_db_p3: "Utilisez Exporter pour télécharger toutes les sessions en fichier <code>.js</code>. Utilisez Importer pour restaurer depuis un fichier exporté — vous pouvez choisir de fusionner ou remplacer les données.",
      help_s_export_title: "Exporter les données",
      help_s_export_p: "Dans la barre utilitaire, utilisez Copier les données pour copier tous les scores dans le presse-papiers en format tabulé (pour Excel ou Google Sheets). Utilisez Exporter CSV dans le panneau Historique pour le journal complet.",
      help_s_shortcuts_title: "Raccourcis clavier",
      help_s_shortcuts_p: "Ctrl + Espace — Tirer un élève aléatoire<br>Ctrl + Shift + K — Ouvrir le créateur d'équipes<br>Ctrl + M — Ouvrir le sélecteur de mode (ou fermer le mode actif)<br>1 / 2 / 3 — Changer de mode (Silence / Discussion / Groupe) quand le sélecteur ou le minuteur plein écran est ouvert<br>W — Activer/désactiver le bruit blanc<br>M — Couper/rétablir le son du bruit blanc<br>[ / ] — Diminuer / augmenter le volume du bruit blanc",
