      btnGotIt: "Verstanden — los geht's!",
      helpSecFilters: "Filter",
      helpTipFilters1: "<strong>Niveau, Thema, Wortart</strong> — verwende diese Filter, um den Wortpool vor einem Spiel einzugrenzen. Wähle mehrere Werte aus; nur Wörter, die <em>allen aktiven Filtern</em> entsprechen, werden angezeigt.",
      helpTipFilters2: "<strong>Filter bleiben erhalten</strong> — beim Wechsel zwischen Spielen bleiben deine Filterauswahlen aktiv. Nutze <strong>Zurücksetzen</strong>, um alles auf „Alle\" zurückzusetzen.",
      helpTipFilters3: "<strong>Mehrere Themen pro Wort</strong> — ein Wort kann mehreren Themen angehören (z. B. „Emotionen, Charakter\"). Es erscheint, sobald eines seiner Themen ausgewählt ist.",
      helpSecVocab: "Vokabelspiele",
      matchPairsLabel: "Paare:",
      helpCardDefMatchTitle: "Definition zuordnen",
      helpCardDefMatchDesc: "Ordne jedes Wort seiner richtigen Definition zu. Klicke eine Wortkarte, dann die passende Definitionskarte. Alle Paare müssen gefunden werden, um zu gewinnen.",
      helpCardHangmanTitle: "Galgenmännchen",
      helpCardHangmanDesc: "Errate das versteckte Wort Buchstabe für Buchstabe. Wähle die erlaubte Anzahl von Fehlern (4–12). Nutze <strong>Hinweis</strong>, um die Definition zu enthüllen.",
      helpCardScrambleTitle: "Buchstabensalat",
      helpCardScrambleDesc: "Die Buchstaben des Wortes sind durchgemischt. Klicke die Buchstaben in der richtigen Reihenfolge, nutze <strong>Hinweis</strong> für einen Buchstabentipp und sende ab.",
      helpCardWordQuestTitle: "Wortsuche",
      helpCardWordQuestDesc: "Eine Definition wird angezeigt. Schalte bis zu 4 progressive Hinweise frei (Synonyme, Buchstabentipps…), um das Wort einzugrenzen, dann tippe deine Antwort.",
      helpCardPhoneticTitle: "Phonetik-Quiz",
      helpCardPhoneticDesc: "Eine IPA-Lautumschrift wird angezeigt. Erkenne das dargestellte Wort — wähle aus 4 Optionen oder tippe die Antwort direkt ein.",
      helpCardSynAntTitle: "Synonyme & Antonyme",
      helpCardSynAntDesc: "Ein Wort wird angezeigt — finde sein Synonym oder Antonym. Wechsle zwischen den Modi Synonym, Antonym oder Beide. Multiple Choice oder freies Tippen.",
      helpSecGrammar: "Grammatikspiele",
      helpCardSentenceTitle: "Satzbausteine",
      helpCardSentenceDesc: "Rekonstruiere einen durchgemischten Satz, indem du die Wörter in der richtigen Reihenfolge anklickst. Die Zielstruktur wird angezeigt; nutze <strong>Hinweis</strong>, um das nächste Wort zu enthüllen.",
      helpCardGapFillTitle: "Lückentext",
      helpCardGapFillDesc: "Ein Wort wurde aus einem Satz entfernt. Tippe das fehlende Wort. Filtere nach Grammatiktyp (Relativsätze, Konditionalsätze…) für gezielte Übungen.",
      helpCardFindErrorTitle: "Fehler finden",
      helpCardFindErrorDesc: "Erkenne den Grammatikfehler in einem Satz. Zwei Modi: <strong>Erkennen</strong> (korrekt oder fehlerhaft auswählen) oder <strong>Umschreiben</strong> (den Satz selbst korrigieren).",
      helpCardDictationTitle: "Diktat",
      helpCardDictationDesc: "Ein Text wird vorgelesen. Tippe was du hörst, Wort für Wort. Wähle Leicht (10% versteckte Wörter), Mittel (50%) oder Schwer (90%).",
      helpSecTools: "Werkzeuge",
      helpCardGrammarPracticeTitle: "Grammatikübung",
