      tutMdb3Title: "Globale Suche",
      tutMdb3Text: "Durchsuchen Sie Schlüsselwörter, Begriffe oder Fragen gleichzeitig in allen Ihren lokalen Dateien.",
      tutMdb4Title: "Datenbankdateien",
      tutMdb4Text: "Jede Kategorie enthält einzelne JS/JSON-Dateien. Klicken Sie auf einen Tab-Button, um Inhalte anzuzeigen und zu bearbeiten.",
      tutMdb5Title: "Datenbankaktionen",
      tutMdb5Text: "Fügen Sie neue Einträge hinzu, erstellen Sie Dateien, führen Sie Dateien zusammen, entfernen Sie Duplikate oder kopieren Sie KI-Prompts.",
      tutMdb6Title: "Suche & Filterung",
      tutMdb6Text: "Filtern Sie Einträge nach Begriffen, Themen, Wortarten, Schwierigkeitsgraden oder benutzerdefinierten Attributen.",
      tutMdb7Title: "Datensatztabelle & Raster",
      tutMdb7Text: "Betrachten und bearbeiten Sie Datensätze direkt. Klicken Sie auf Zeilen zur Bearbeitung oder wählen Sie mehrere für Stapelaktionen.",
      tutMdb8Title: "Exportoptionen",
      tutMdb8Text: "Exportieren Sie Ihre Datensätze in den Formaten CSV, Excel (XLSX), Word (DOCX), HTML oder druckbarem PDF.",
      alert_no_groups: "Keine Gruppen gefunden.",
      tm_no_sessions: "Noch keine gespeicherten Sitzungen.\nVerwenden Sie Speichern, um eine Sitzung zu erfassen.",
      tm_readonly_badge: "Nur lesen",
      help_s_groups_title: "Gruppen",
      help_s_groups_p: "Wählen Sie eine Klasse mit den Schaltflächen oben auf der Seite aus. Die Liste wird sofort aktualisiert. Sie können jederzeit die Gruppe wechseln — Punkte und Striche werden pro Gruppe für die Dauer der Sitzung gespeichert.",
      help_s_picker_title: "Zufälliger Schüler",
      help_s_picker_p: "Drücken Sie Zufälliger Schüler (oder Strg + Leertaste), um einen Schüler zufällig auszuwählen. Bereits ausgewählte Schüler werden durchgestrichen. Klicken Sie direkt auf einen Schülernamen, um ihn manuell durchzustreichen — nützlich bei Abwesenheit. Verwenden Sie Striche zurücksetzen in der Utility-Leiste, um eine neue Runde zu starten. Klicken Sie auf Trommelwirbel für mehr Spannung.",
      help_s_points_title: "Punkte",
      help_s_points_p: "Jeder Schüler hat +- und --Schaltflächen. Plus vergibt einen Teilnahmepunkt; Minus erfasst eine Warnung oder eine verpasste Aufgabe. Die grünen und roten Punktzähler sind anklickbar: Ein Klick verringert den jeweiligen Zähler um eins, um Fehleingaben zu korrigieren. Punkte fließen in das Live-Ranking und die Abschlussergebnisse ein.",
      help_s_badges_title: "Abzeichen",
      help_s_badges_p: "Jeder Schüler kann Emoji-Abzeichen als Belohnung erhalten. Klicken Sie auf die Abzeichen-Schaltfläche einer Zeile, um die Auswahl zu öffnen. Abzeichen häufen sich an und werden neben den Namen angezeigt. Verwenden Sie den Abzeichen-Schalter im Listenkopf zum Ein-/Ausblenden der Spalte. Um ein Abzeichen zu entfernen, klicken Sie direkt auf den Abzeichen-Chip.",
      help_s_notes_title: "Notizen",
      help_s_notes_p: "Klicken Sie auf den Punkt-Indikator einer Zeile, um ein privates Notiz-Popup zu öffnen. Geben Sie eine kurze Notiz ein und drücken Sie Enter oder Speichern. Notizen sind privat — sie werden nicht auf dem Bildschirm angezeigt. Ein ausgefüllter Punkt zeigt an, dass eine Notiz vorhanden ist.",
      help_s_timer_title: "Timer",
      help_s_timer_p: "Klicken Sie auf Timer im Menü, um das Popup zu öffnen. Stellen Sie die Dauer in Stunden und Minuten ein, konfigurieren Sie die Anzahl der Schlusssignale und drücken Sie Starten. Der Countdown erscheint in der Menüleiste. Drücken Sie für eine farbige Vollbildanzeige — nützlich für den Projektor: wechselt von Grün über Orange zu Rot. Schalten Sie auf den Stoppuhr-Modus um, um aufwärts zu zählen.",
      help_s_objectives_title: "Lernziele",
      help_s_objectives_p: "Klicken Sie auf Ziele im Menü, um den Editor zu öffnen. Geben Sie ein oder mehrere Ziele ein und speichern Sie — sie erscheinen in einer Leiste unter dem Titel und im Vollbild-Timer. Klicken Sie auf den Leistentext oder die Schaltfläche Bearbeiten, um sie jederzeit zu aktualisieren.",
      help_s_mode_title: "Klassenmodus",
      help_s_mode_p: "Drücken Sie Modus im Menü (oder Strg + M), um einen Arbeitsmodus zu wählen: Stille Arbeit, Gespräch oder Gruppenarbeit. Jeder Modus öffnet eine animierte Vollbildanzeige für den Projektor. Sie können Modi auch direkt aus dem Timer-Popup über die drei Schnellzugriff-Schaltflächen starten. Drücken Sie die Schließen-Schaltfläche oder Strg + M, um die Anzeige zu schließen.",
      help_s_teams_title: "Teams",
      help_s_teams_p: "Drücken Sie Teams erstellen (oder Strg + Umschalt + K), um den Team-Ersteller zu öffnen. Wählen Sie entweder eine Gesamtzahl von Teams oder eine Anzahl von Schülern pro Team. Sie können Schüler per Drag & Drop zwischen Teams verschieben oder eine Team-Karte auf eine andere ziehen, um sie zusammenzuführen. Verwenden Sie Neu mischen oder Teams löschen.",
      help_s_roles_title: "Team-Rollen",
      help_s_roles_p: "Sobald Teams erstellt sind, klicken Sie auf Rollen, um den Editor zu öffnen. Verwenden Sie + zum Hinzufügen von Rollennamen (z.B. Kapitän, Schriftführer, Zeitnehmer, Sprecher). Klicken Sie auf An Schüler verteilen, um zufällig eine Rolle pro Schüler zuzuweisen. Rollen erscheinen kursiv. Verwenden Sie Alle Rollen zurücksetzen zum Löschen.",
      help_s_results_title: "Ergebnisse und Ranking",
      help_s_results_p: "Klicken Sie auf Ergebnisse &amp; Ranking, um das Live-Ergebnisfenster zu öffnen. Der obere Abschnitt zeigt eine vollständige Rangliste nach Punktzahl. Der untere Abschnitt zeigt das Podium des Tages — Gold, Silber und Bronze — sowie Team-Durchschnittswerte, wenn Teams aktiv sind.",
      help_s_history_title: "Sitzungsverlauf",
      help_s_history_p: "Klicken Sie auf Verlauf, um ein chronologisches Protokoll aller Aktionen der Sitzung anzuzeigen. Verwenden Sie CSV exportieren zum Herunterladen. Verwenden Sie Löschen, um das Protokoll zurückzusetzen.",
      help_s_db_title: "Datenbank &amp; Zeitmaschine",
      help_s_db_p1: "Klicken Sie auf DB im Menü. Verwenden Sie Speichern, um die aktuell ausgewählte Klasse zu sichern, oder Alle speichern für alle Gruppen auf einmal. Wurde eine Klasse heute bereits gespeichert, wird sie lautlos überschrieben.",
      help_s_db_p2: "Klicken Sie auf Zeitmaschine, um gespeicherte Sitzungen zu durchsuchen. Drücken Sie Anzeigen, um einen Schnappschuss zu laden — die App wechselt in den Nur-Lese-Modus. Ein lila Banner zeigt die angezeigte Sitzung an. Drücken Sie Zurück zur Live-Sitzung, um Ihre aktuelle Sitzung wiederherzustellen.",
      help_s_db_p3: "Verwenden Sie Exportieren, um alle Sitzungen als <code>.js</code>-Datei herunterzuladen. Verwenden Sie Importieren, um aus einer exportierten Datei wiederherzustellen.",
      help_s_export_title: "Daten exportieren",
      help_s_export_p: "Verwenden Sie in der Utility-Leiste Daten kopieren, um alle Schülerpunkte in die Zwischenablage zu kopieren (tabulatorgetrennt, für Excel oder Google Sheets). Verwenden Sie CSV exportieren im Verlaufs-Panel für das vollständige Protokoll.",
      help_s_shortcuts_title: "Tastaturkürzel",
      help_s_shortcuts_p: "Strg + Leertaste — Zufälligen Schüler auswählen<br>Strg + Umschalt + K — Team-Ersteller öffnen<br>Strg + M — Modusauswahl öffnen (oder aktiven Modus schließen)<br>1 / 2 / 3 — Modus wechseln (Stille / Gespräch / Gruppe)<br>W — Weißes Rauschen ein-/ausschalten<br>M — Weißes Rauschen stummschalten/aufheben<br>[ / ] — Lautstärke verringern / erhöhen",
