      conInstructions: "Sistema: clic destro sulla lavagna per aggiungere parole (virgola = parole separate, + = parole raggruppate, -- = catena collegata) · Sposta: trascina le parole e rilasciale su un'altra parola per raggruppare · Scorciatoie: Ctrl/Cmd+clic selezione multipla, Ctrl/Cmd+G raggruppa, Canc/Backspace elimina, Esc chiude i menu, Ctrl/Cmd+Y o Ctrl/Cmd+Shift+Z ripristina",
      helpTitle: "Come Funziona",
      helpSubtitle: "Una guida completa — filtri, giochi, strumenti e modalità a squadre.",
      btnGotIt: "Capito — giochiamo!",
      helpSecFilters: "Filtri",
      helpTipFilters1: "<strong>Livello, Tema, Tipo</strong> — usa questi filtri per restringere il pool di parole prima di iniziare un gioco. Seleziona più valori da qualsiasi selettore; appariranno solo le parole che corrispondono a <em>tutti i filtri attivi</em>.",
      helpTipFilters2: "<strong>I filtri si mantengono</strong> — quando navighi da un gioco all'altro, le tue selezioni rimangono attive. Usa <strong>Reimposta</strong> per tornare a \"Tutti\".",
      helpTipFilters3: "<strong>Temi multipli per parola</strong> — una parola può appartenere a più temi (es. \"Emozioni, Carattere\"). Apparirà ogni volta che uno dei suoi temi è selezionato.",
      helpSecVocab: "Giochi di Vocabolario",
      matchPairsLabel: "Coppie:",
      helpCardDefMatchTitle: "Abbina la Definizione",
      helpCardDefMatchDesc: "Abbina ogni parola alla sua definizione corretta. Clicca una carta-parola, poi la carta-definizione corrispondente. Devi trovare tutte le coppie per vincere.",
      helpCardHangmanTitle: "L'Impiccato",
      helpCardHangmanDesc: "Indovina la parola nascosta lettera per lettera. Scegli il numero di errori consentiti (4–12). Usa <strong>Indizio</strong> per rivelare la definizione.",
      helpCardScrambleTitle: "Parola Mescolata",
      helpCardScrambleDesc: "Le lettere della parola sono mescolate. Clicca le lettere per comporre la risposta, usa <strong>Indizio</strong> per un suggerimento, poi invia.",
      helpCardWordQuestTitle: "Caccia alla Parola",
      helpCardWordQuestDesc: "Viene mostrata una definizione. Sblocca fino a 4 indizi progressivi (sinonimi, suggerimenti di lettere…) per restringere le possibilità, poi digita la tua risposta.",
      helpCardPhoneticTitle: "Fonetica",
      helpCardPhoneticDesc: "Viene mostrata una trascrizione fonetica IPA. Identifica la parola che rappresenta — scegli tra 4 opzioni o digita la risposta direttamente.",
      helpCardSynAntTitle: "Sinonimi & Contrari",
      helpCardSynAntDesc: "Viene mostrata una parola — trova il suo sinonimo o contrario. Alterna tra le modalità Sinonimo, Contrario o Entrambi. Scelta multipla o digitazione libera.",
      helpSecGrammar: "Giochi di Grammatica",
      helpCardSentenceTitle: "Costruisci la Frase",
      helpCardSentenceDesc: "Ricostruisci una frase mescolata cliccando le parole nell'ordine corretto. La struttura target è mostrata; usa <strong>Indizio</strong> per rivelare la parola successiva.",
      helpCardGapFillTitle: "Riempi il Vuoto",
      helpCardGapFillDesc: "Una parola è stata rimossa da una frase. Digita la parola mancante. Filtra per tipo grammaticale (Relative, Condizionali…) per esercizi mirati.",
      helpCardFindErrorTitle: "Trova l'Errore",
      helpCardFindErrorDesc: "Individua l'errore grammaticale in una frase. Due modalità: <strong>Individua</strong> (scegli tra corretta ed errata) o <strong>Riscrivi</strong> (correggi la frase tu stesso).",
      helpCardDictationTitle: "Dettato",
      helpCardDictationDesc: "Un testo viene letto ad alta voce. Digita quello che senti, parola per parola. Scegli Facile (10% parole nascoste), Medio (50%) o Difficile (90%).",
      helpSecTools: "Strumenti",
      helpCardGrammarPracticeTitle: "Esercizi di Grammatica",
      helpCardGrammarPracticeDesc: "Una biblioteca di riferimento per le regole grammaticali — formule, parole segnale, errori comuni e consigli. Filtra per categoria o livello.",
      helpCardFlashCardsTitle: "Flashcard",
      helpCardFlashCardsDesc: "Passa il mouse su una carta per girarla e scoprire la traduzione francese e la definizione. Ottimo per la revisione passiva.",
      helpCardQuoteTitle: "Analisi Citazione",
      helpCardQuoteDesc: "Viene visualizzata una citazione letteraria. Indovina il tema e le parole chiave; sblocca gli indizi uno alla volta o richiedi un'analisi completa.",
      helpCardViewWordsTitle: "Tutti i Vocaboli",
